package com.desktodo.app;
import android.app.*;import android.widget.*;import org.json.*;import java.time.*;import java.util.*;
/** Scene previews use the same renderer and current data as the physical frame. */
final class ScreenPanel {
 final MainActivity a;String selected="work";
 ScreenPanel(MainActivity a){this.a=a;}
 void preview(LinearLayout parent,JSONObject config){try{DeskRenderer renderer=new DeskRenderer(null,a.tasks,ScreenData.renderConfig(config,a.completions,Instant.now()),a.weather,a.quotes);renderer.full(DeskModel.layoutId(config));ImageView image=new ImageView(a);image.setImageBitmap(renderer.image);image.setAdjustViewBounds(true);image.setContentDescription("800乘480真实排版预览，点击查看大图");image.setOnClickListener(v->{ScrollView vertical=new ScrollView(a);HorizontalScrollView horizontal=new HorizontalScrollView(a);ImageView large=new ImageView(a);large.setImageBitmap(renderer.image);large.setAdjustViewBounds(true);horizontal.addView(large,new android.view.ViewGroup.LayoutParams(a.dp(800),a.dp(480)));vertical.addView(horizontal);new AlertDialog.Builder(a).setTitle("排版大图 · 可拖动查看").setView(vertical).setPositiveButton("关闭",null).show();});parent.addView(image,new LinearLayout.LayoutParams(-1,-2));parent.addView(a.text("点击放大 · 当前手机数据 · 应用场景全刷一次",12,a.muted));}catch(Exception e){parent.addView(a.text("预览暂不可用："+e.getMessage(),13,AppUi.DANGER));}}
 void scenes(){LinearLayout l=a.card("选择一种桌面节奏");l.addView(a.text("场景决定内容组合，排版仍可单独调整。没有设备也能预览；应用前会明确确认。",14,a.muted));String[] ids={"work","focus","life"},names={"工作桌面","专注桌面","生活画报"},details={"大待办＋生长盆栽＋重要日","真实计时＋当前事项","农历节气＋月历＋四时插画"};for(int i=0;i<3;i++){String id=ids[i];AppUi.row(a,l,names[i]+(selected.equals(id)?"  ✓":""),details[i],()->{selected=id;a.draw();});}try{JSONObject choice=ScreenData.scene(a.cfg,selected);LinearLayout p=a.card("应用前预览");preview(p,choice);}catch(Exception e){a.toast(e.getMessage());}a.primary(a.dock,"应用此场景",()->apply());}
 void apply(){if(a.busy||a.resolvingConflict){a.toast("请先完成同步或清单选择");return;}if(!a.connected){a.toast("请先在设备连接页连接，再应用场景");return;}new AlertDialog.Builder(a).setTitle("应用场景？").setMessage("本次全刷一次，保留当前待办。固定红色保持品牌装饰，普通内容变化仍局刷。场景不会自动轮播。").setNegativeButton("再看看",null).setPositiveButton("确认应用",(d,w)->{try{a.cfg=ScreenData.scene(a.cfg,selected);a.stagedLayout=null;a.screenChanged();a.sync(true,true);}catch(Exception e){a.toast(e.getMessage());}}).show();}
 void cards(){LinearLayout l=a.card("搭配右侧卡片");l.addView(a.text("用于专注清单、日程安排和信息总览。保存后独立局刷；专注/生活画报保留自身结构。",14,a.muted));Spinner first=a.cardSpinner(l,"上方卡片",ScreenData.CARD_NAMES,ScreenData.CARD_KEYS,"card1"),second=a.cardSpinner(l,"下方卡片",ScreenData.CARD_NAMES,ScreenData.CARD_KEYS,"card2");EditText goal=a.field(l,"本周目标（1–999）",String.valueOf(a.cfg.optInt("weeklyGoal",20)));goal.setInputType(2);EditText note=a.field(l,"桌面小纸条",a.cfg.optString("note"));a.primary(l,"保存并局部同步",()->{try{int n=Integer.parseInt(goal.getText().toString());if(n<1||n>999||note.length()>100)throw new Exception("目标1至999，小纸条最多100字");a.cfg.put("cardsVersion",1).put("card1",ScreenData.CARD_KEYS[first.getSelectedItemPosition()]).put("card2",ScreenData.CARD_KEYS[second.getSelectedItemPosition()]).put("weeklyGoal",n).put("note",note.getText().toString());for(String hint:new String[]{"card1","card2","本周目标（1–999）","桌面小纸条"})a.clearDraft(hint);a.hideKeyboard();a.screenChanged();a.sync(false,false);}catch(Exception e){a.toast(e.getMessage());}});LinearLayout progress=a.card("本机本周");int count=ScreenData.weekCount(a.completions,Instant.now());progress.addView(a.text("已完成 "+count+" 项 · 生长阶段 "+ScreenData.plantStage(count,a.cfg.optInt("weeklyGoal",20))+" / 5",18,a.ink));progress.addView(a.text("只统计本机完成记录，周一开始；撤销完成会扣回。暂不与 Mac 历史合并。",13,a.muted));preview(a.card("当前配置预览"),a.cfg);a.button(a.body,"管理重要日期",()->a.openPage("重要日期"));a.button(a.body,"设置办公状态",()->a.openPage("办公状态"));}
 void dates(){LinearLayout intro=a.card("重要的日子");intro.addView(a.text("最多十二个，优先显示最近的未来日期。按北京时间自然日计算，跨日更新。",14,a.muted));a.primary(intro,"＋ 添加重要日期",this::addDate);JSONArray dates=a.cfg.optJSONArray("dates");if(dates!=null)for(int i=0;i<dates.length();i++){JSONObject item=dates.optJSONObject(i);String id=item.optString("id");LinearLayout row=a.card(item.optString("title"));row.addView(a.text(item.optString("date"),16,a.ink));a.button(row,"移除日期",()->new AlertDialog.Builder(a).setTitle("移除这个日期？").setNegativeButton("取消",null).setPositiveButton("移除",(d,w)->{try{JSONArray next=new JSONArray();JSONArray current=a.cfg.optJSONArray("dates");for(int n=0;current!=null&&n<current.length();n++)if(!current.optJSONObject(n).optString("id").equals(id))next.put(current.optJSONObject(n));a.cfg.put("dates",next);a.screenChanged();a.sync(false,false);}catch(Exception e){a.toast(e.getMessage());}}).show());}a.body.addView(a.text(ScreenData.countdown(a.cfg,Instant.now()).replace("\n"," · "),16,a.green));}
 void addDate(){if(a.cfg.optJSONArray("dates")!=null&&a.cfg.optJSONArray("dates").length()>=12){a.toast("最多十二个重要日期");return;}LinearLayout form=new LinearLayout(a);form.setOrientation(1);form.setPadding(a.dp(20),0,a.dp(20),0);EditText title=a.field(form,"日期名称（最多30字）","");LocalDate[] selected={LocalDate.now(ScreenData.ZONE)};Button date=a.button(form,"选择日期 · "+selected[0],()->new DatePickerDialog(a,(v,y,m,d)->{selected[0]=LocalDate.of(y,m+1,d);for(int n=0;n<form.getChildCount();n++)if(form.getChildAt(n) instanceof Button)((Button)form.getChildAt(n)).setText("目标日期 · "+selected[0]);},selected[0].getYear(),selected[0].getMonthValue()-1,selected[0].getDayOfMonth()).show());AlertDialog dialog=new AlertDialog.Builder(a).setTitle("添加重要日期").setView(a.scrollForm(form)).setNegativeButton("取消",null).setPositiveButton("保存",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(b->{try{a.cfg=ScreenData.datesConfig(a.cfg,title.getText().toString(),selected[0]);a.clearDraft("日期名称（最多30字）");a.screenChanged();dialog.dismiss();a.sync(false,false);}catch(Exception e){title.setError(e.getMessage());}}));dialog.show();}
 void status(){LinearLayout l=a.card("办公状态牌");l.addView(a.text("可以显示在工作桌面的右侧卡片。状态由你手动设置，不会推测你是否正在开会。",14,a.muted));String[] states={"专注中","开会中","暂时离开","今日已下班"};Spinner choice=new Spinner(a);choice.setMinimumHeight(a.dp(48));choice.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,states));for(int i=0;i<states.length;i++)if(states[i].equals(a.drafts.getOrDefault(a.page+"|deskStatus",a.cfg.optString("deskStatus"))))choice.setSelection(i);choice.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> parent,android.view.View view,int position,long id){a.drafts.put(a.page+"|deskStatus",states[position]);}public void onNothingSelected(AdapterView<?> parent){}});l.addView(choice);EditText note=a.field(l,"状态补充（最多30字）",a.cfg.optString("statusNote","请稍后联系"));a.primary(l,"保存并显示状态牌",()->{try{if(note.length()>30)throw new Exception("补充最多30字");a.cfg.put("cardsVersion",1).put("deskStatus",states[choice.getSelectedItemPosition()]).put("statusNote",note.getText().toString()).put("card2","status");a.clearDraft("状态补充（最多30字）");a.clearDraft("deskStatus");a.hideKeyboard();a.screenChanged();a.sync(false,false);}catch(Exception e){a.toast(e.getMessage());}});preview(a.card("当前配置预览"),a.cfg);}
 void focus(){long now=System.currentTimeMillis();LinearLayout l=a.card(ScreenData.focusState(a.cfg,now));long left=ScreenData.focusRemaining(a.cfg,now);l.addView(a.text((left>0||a.cfg.optLong("focusEnd",0)>0?(left+59999)/60000:a.cfg.optInt("focusMinutes",25))+" 分钟",40,a.ink));l.addView(a.text(a.cfg.optString("focusTask","为自己留一段专注时间"),16,a.muted));EditText minutes=a.field(l,"专注时长（5–90分钟）",String.valueOf(a.cfg.optInt("focusMinutes",25)));minutes.setInputType(2);if(a.cfg.optLong("focusEnd",0)>now)a.button(l,"暂停",()->focusAction("pause",minutes));else if(a.cfg.optLong("focusPaused",0)>0)a.primary(l,"继续专注",()->focusAction("resume",minutes));else a.primary(l,"开始专注",()->focusAction("start",minutes));a.button(l,"结束本段",()->focusAction("stop",minutes));a.button(l,"选择当前事项",()->{String[] names=new String[a.tasks.length()];for(int i=0;i<names.length;i++)names[i]=a.tasks.optJSONObject(i).optString("title");if(names.length==0){a.toast("请先添加一项待办");return;}new AlertDialog.Builder(a).setTitle("专注哪件事？").setItems(names,(d,n)->{try{a.cfg.put("focusTask",names[n]);a.screenChanged();a.sync(false,false);}catch(Exception e){a.toast(e.getMessage());}}).show();});a.button(l,"切换到专注场景",()->{selected="focus";a.openPage("选择场景");});l.addView(a.text("屏幕只显示剩余分钟，手机前台会更新。锁屏后到期通知由系统闹钟安排；屏幕会在重新连接时校正。",13,a.muted));if(!ReminderScheduler.permitted(a))a.button(l,"允许通知，接收专注完成提醒",()->{if(android.os.Build.VERSION.SDK_INT>=33&&a.checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=0)a.requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},31);else a.openPage("本地提醒");});}
 void focusAction(String action,EditText minutes){try{if(action.equals("start")){int n=Integer.parseInt(minutes.getText().toString());if(n<5||n>90)throw new Exception("请输入5至90分钟");a.cfg.put("focusMinutes",n);}a.cfg=ScreenData.focus(a.cfg,action,System.currentTimeMillis());a.clearDraft("专注时长（5–90分钟）");a.hideKeyboard();a.screenChanged();a.sync(false,false);}catch(Exception e){a.toast(e.getMessage());}}
}
